INSERT INTO atom_descriptions (atom_key, description) VALUES ('----', 'Freeform metadata item. Reverse-DNS keyed custom tag used by iTunes and other tools for extended metadata fields.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('XMP_', 'XMP metadata box. Embeds Adobe XMP metadata for photo/video workflows.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('aART', 'Album artist metadata tag. Album-level artist name.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('catg', 'Category metadata tag. Podcast category text.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('clip', 'Clipping region box. Legacy QuickTime clipping metadata.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('co64', '64-bit Chunk Offset box. Same as stco, but uses 64-bit offsets for large files.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('covr', 'Cover Art metadata item. Embedded thumbnail or album artwork stored inside ilst.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('cpil', 'Compilation metadata tag. Marks track as part of a compilation album.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('cprt', 'Copyright metadata tag. Copyright statement.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('ctts', 'Composition Time to Sample box. Maps decode order to presentation order for B-frame video streams.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('desc', 'Description metadata tag. Longer description, common in podcasts.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('dinf', 'Data Information box. Container for data reference information for a track.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('disk', 'Disc number metadata tag. Disc index and total disc count.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('dref', 'Data Reference box. Describes where media data lives, usually self-contained in the same file.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('edts', 'Edit box. Contains edit lists that trim or shift track timeline for playback.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('egid', 'Episode GUID metadata tag. Unique podcast episode identifier.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('elst', 'Edit List box. Specifies media time ranges and playback rate edits for a track.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('free', 'Free Space box. Padding that can be reused later without rewriting the whole file. Sometimes used to reserve space for metadata updates.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('ftyp', 'File Type box. Identifies the file as MP4/MOV, declares the major brand (for example mp42 or isom), and lists compatible brands players should accept.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('gap', 'Unclassified byte range. These bytes were not parsed as a known atom, which may indicate corruption, custom data, or an unsupported atom type.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('gmhd', 'Generic Media Header box. Container for base media info in generic tracks.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('gmin', 'Base Media Info box. Part of MPEG-4 systems media information.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('gnre', 'Genre ID metadata tag. Legacy iTunes genre identifier.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('hdlr', 'Handler Reference box. Declares what kind of track this is (vide, soun, meta, subt, etc.) and the component name of the handler.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('hmhd', 'Hint Media Header box. Used for hint tracks in streaming scenarios.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('ilst', 'Item List box. Stores iTunes-style metadata tags such as title, artist, encoder, and cover art.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('ipro', 'Item Protection box. Protection information for individual items.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('keys', 'Metadata keys box. Defines keys used by mdta-style tagged metadata.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('keyw', 'Keywords metadata tag. Search keywords for the media item.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mdat', 'Media Data box. Contains the raw encoded video, audio, and subtitle sample bytes. This is usually the largest part of the file.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mdhd', 'Media Header box. Defines media timescale, duration, and language for a track.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mdia', 'Media box. Container for a track''s media information: handler, media header, and sample table.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('meco', 'Additional Metadata Container box. Extended metadata container in some MP4 files.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('merc', 'Additional Metadata Relation Container box. Groups related extended metadata.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mere', 'Additional Metadata Relation box. Describes relationships between metadata items.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('meta', 'Metadata box. Wrapper for metadata handler and item list (often ilst tags).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mfhd', 'Movie Fragment Header box. Sequence number for a moof fragment.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mfra', 'Movie Fragment Random Access box. Index to support random access in fragmented files.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mfro', 'Movie Fragment Random Access Offset box. Offset to the mfra index.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('minf', 'Media Information box. Groups sample description and sample table data needed to locate and decode track samples.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('moof', 'Movie Fragment box. Header for one fragment in fragmented MP4 used for streaming.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('moov', 'Movie box. Top-level metadata container holding track descriptions, sample tables, duration, and user metadata required to decode and play the file.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mvex', 'Movie Extends box. Declares defaults used by fragmented MP4 tracks.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('mvhd', 'Movie Header box. Stores global timing: timescale, duration, creation date, and preferred playback rate for the entire presentation.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('nmhd', 'Null Media Header box. Used for tracks without specific media header values.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('pcst', 'Podcast metadata tag. Marks the file as a podcast.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('pgap', 'Gapless playback metadata tag. Indicates album gapless playback intent.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('psmt', 'Presentation metadata box. Used in some broadcast and professional MP4 variants.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('pssh', 'Protection System Specific Header box. DRM initialization data for encrypted streams (Widevine, PlayReady, etc.).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('purl', 'Podcast URL metadata tag. Podcast feed or episode URL.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('rtng', 'Content rating metadata tag. Age/content rating value.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('schi', 'Scheme Information box. Child container for protection scheme details.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('sdtp', 'Independent and Disposable Samples box. Flags whether samples depend on other samples and whether they are disposable.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('sidx', 'Segment Index box. Index for progressive download or streaming byte ranges.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('sinf', 'Protection Scheme Information box. DRM/protection wrapper for encrypted samples.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('skip', 'Skip box. Opaque padding similar to free; readers should ignore its contents.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('smhd', 'Sound Media Header box. Audio balance and reserved sound header fields.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stbl', 'Sample Table box. Container for tables mapping sample numbers to sizes, timestamps, chunk locations, and codec descriptions.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stco', 'Chunk Offset box. Lists byte offsets of each chunk in the file (32-bit offsets).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stik', 'Media kind metadata tag. Indicates whether the file is a movie, music video, podcast, etc.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stsc', 'Sample To Chunk box. Defines how samples are grouped into chunks in mdat.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stsd', 'Sample Description box. Lists codec-specific sample entry atoms (avc1, mp4a, etc.) describing how to decode each sample.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stss', 'Sync Sample box. Lists keyframe/sample numbers used as random access points.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stsz', 'Sample Size box. Gives the size of each sample or a default sample size.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('stts', 'Decoding Time to Sample box. Maps each sample to its duration in media time.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('styp', 'Segment Type box. Same role as ftyp, but for fragmented MP4 segments. Used in DASH/HLS streaming files.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tfdt', 'Track Fragment Base Media Decode Time box. Base decode timestamp for samples in the fragment.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tfhd', 'Track Fragment Header box. Defaults and flags for sample data in a traf.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tfra', 'Track Fragment Random Access box. Random access entries for one track.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tkhd', 'Track Header box. Stores track identity, duration, layer, volume, transformation matrix, and display width/height.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tmpo', 'Tempo metadata tag. Beats per minute for music tracks.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('traf', 'Track Fragment box. Track-specific tables for one fragment.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('trak', 'Track box. Describes one media stream such as video, audio, subtitles, or metadata. Each trak contains timing, handler type, and sample information.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('trex', 'Track Extends box. Default sample description and duration for a track in fragmented MP4.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('trkn', 'Track number metadata tag. Track index and total track count.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('trun', 'Track Fragment Run box. Per-sample sizes, durations, flags, and composition offsets for a fragment.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('udta', 'User Data box. Container for custom metadata not covered by the sample tables.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('unparsed', 'Unparsed data region. The parser could not interpret this range as a valid atom structure starting at this offset.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('uuid', 'UUID extension box. Vendor-specific or standard metadata payload identified by a 128-bit UUID (for example XMP or proprietary camera data).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('vmhd', 'Video Media Header box. Video-specific flags such as graphics mode and opcolor.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('wave', 'Wave audio extension box. Wraps Microsoft-style audio sample descriptions.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('wide', 'Wide box. Legacy placeholder/padding atom occasionally seen before mdat.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('xml ', 'XML metadata box. Embeds XML metadata payload inside the file.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©ART', 'Artist metadata tag (©ART). Creator or performer name.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©alb', 'Album metadata tag (©alb). Album or collection name.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©cmt', 'Comment metadata tag (©cmt). Free-form comment text.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©cpy', 'Copyright metadata tag. Copyright notice text.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©day', 'Date metadata tag (©day). Release or recording date.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©gen', 'Genre metadata tag (©gen). Genre description.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©lyr', 'Lyrics metadata tag (©lyr). Song lyrics text.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©nam', 'Title metadata tag (©nam). Human-readable track or video title.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©too', 'Encoder metadata tag (©too). Software that encoded the file.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('©wrt', 'Composer metadata tag (©wrt). Composer or writer credit.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('csgm', 'Compact Sample to Group box. A space-efficient QuickTime variant of the Sample to Group box (sbgp) that maps samples to sample groups using compact tables (ISO 14496-12 / QuickTime).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('cslg', 'Composition to Decode box. Maps composition time to decode time when signed composition offsets (ctts) are used, and records timeline values such as the least decode-to-display delta for the track (ISO 14496-12).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('sbgp', 'Sample to Group box. Maps runs of samples to sample group entries identified by grouping_type. Used with sgpd to classify samples for random access, roll groups, stereo views, and similar features (ISO 14496-12).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('sgpd', 'Sample Group Description box. Defines the properties of sample groups referenced by sbgp. Each grouping_type links to one or more group description entries with type-specific parameters (ISO 14496-12).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tapt', 'Track Aperture Mode Dimensions box. QuickTime container that defines display geometry for a video track, usually containing clef (clean aperture), prof (production aperture), and enof (encoded pixels) dimension sub-atoms.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tref', 'Track Reference box. Container for track reference type atoms that define relationships between tracks, such as hint sources, timecode tracks, alternate groups, or synchronized media (ISO 14496-12 / QuickTime).');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('cdsc', 'Track reference type cdsc. Lists track IDs of metadata or chapter tracks that describe this track.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('cdep', 'Track reference type cdep. Lists track IDs of tracks that this track depends on.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('sync', 'Track reference type sync. Lists track IDs of tracks used as sync sample references.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('hint', 'Track reference type hint. Lists track IDs of hint tracks derived from this track.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('tmcd', 'Track reference type tmcd. Lists track IDs of timecode tracks associated with this track.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('dpnd', 'Track reference type dpnd. Lists track IDs of tracks this track depends on for decoding or playback.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('clef', 'Track Clean Aperture Dimensions atom. Part of tapt; defines clean aperture width and height for display.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('prof', 'Track Production Aperture Dimensions atom. Part of tapt; defines production aperture width and height.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('enof', 'Track Encoded Pixels Dimensions atom. Part of tapt; defines encoded pixel width and height.');
INSERT INTO atom_descriptions (atom_key, description) VALUES (char(0,0,0,0), 'Terminator atom (QuickTime type 0x00000000). Marks the end of an audio decompressor atom list inside a wave box; readers should ignore it.');
INSERT INTO atom_descriptions (atom_key, description) VALUES (char(0,0,0,1), 'Numeric QuickTime atom type 0x00000001. Documented as a sprite property matrix atom (MatrixRecord) in legacy QuickTime sprite tracks. The same byte pattern also appears inside metadata data atoms as a UTF-8 type indicator.');
INSERT INTO atom_descriptions (atom_key, description) VALUES (char(0,0,0,2), 'Numeric QuickTime atom type 0x00000002. Non-ASCII 32-bit atom type used in some legacy QuickTime structures and extension fields; not assigned a public four-character name in Apple''s atom reference.');
INSERT INTO atom_descriptions (atom_key, description) VALUES (char(0,0,0,3), 'Numeric QuickTime atom type 0x00000003. Non-ASCII 32-bit atom type used in some legacy QuickTime structures and extension fields; not assigned a public four-character name in Apple''s atom reference.');
INSERT INTO atom_descriptions (atom_key, description) VALUES (char(0,0,0,4), 'Numeric QuickTime atom type 0x00000004. Documented as a sprite visible property atom (short) in legacy QuickTime sprite tracks.');
INSERT INTO atom_descriptions (atom_key, description) VALUES (char(0,0,0,5), 'Numeric QuickTime atom type 0x00000005. Sprite property layer atom (short) in legacy QuickTime sprite tracks.');
INSERT INTO atom_descriptions (atom_key, description) VALUES (char(0,0,0,6), 'Numeric QuickTime atom type 0x00000006. Sprite graphics mode property atom in legacy QuickTime sprite tracks.');
INSERT INTO atom_descriptions (atom_key, description) VALUES ('data', 'Metadata data atom. Wraps a typed value inside an ilst item; the payload begins with a 4-byte type indicator (1 = UTF-8 text, 13 = JPEG cover art, etc.) and a locale field.');
